INSERT INTO standards (standard_id, code, description, subject, grade_level) VALUES (3001, '3.NF.2', 'Understand a fraction as a number on the number line; represent fractions on a number line diagram.', 'Mathematics', 'Grade 3');
INSERT INTO standards (standard_id, code, description, subject, grade_level) VALUES (5001, '5.R.6', 'Determine the theme or main idea of a text, including texts from diverse cultures, explain how it is conveyed through particular details, and summarize the text.', 'English Language Arts', 'Grade 5');
INSERT INTO standards (standard_id, code, description, subject, grade_level) VALUES (7001, '7.RP.2', 'Recognize and represent proportional relationships between quantities, including determining the constant of proportionality, representing relationships with equations and graphs, and interpreting points in context.', 'Mathematics', 'Grade 7');
INSERT INTO standards (standard_id, code, description, subject, grade_level) VALUES (8001, 'SCI.8.1.5', 'Develop a model that uses computational thinking to illustrate cause and effect relationships in particle motion, temperature, density, and state of a pure substance when heat energy is added or removed.', 'Science', 'Grade 8');
INSERT INTO standards (standard_id, code, description, subject, grade_level) VALUES (3002, '3.R.6', 'Determine the main idea or theme of a text and explain how key details support it; summarize the text.', 'English Language Arts', 'Grade 3');
INSERT INTO standards (standard_id, code, description, subject, grade_level) VALUES (5002, '5.NF.5', 'Interpret multiplication as scaling and explain how the size of a product relates to the size of its factors.', 'Mathematics', 'Grade 5');
INSERT INTO standard_core_ideas (core_idea_id, standard_id, name, description, sort_order) VALUES (3101, 3001, 'Partition the whole into equal intervals', 'Define 0 to 1 as one whole and partition it into equal parts.', 1);
INSERT INTO standard_core_ideas (core_idea_id, standard_id, name, description, sort_order) VALUES (3102, 3001, 'Locate unit fractions on a number line', 'Locate 1/b on a number line using equal intervals.', 2);
INSERT INTO standard_core_ideas (core_idea_id, standard_id, name, description, sort_order) VALUES (3103, 3001, 'Locate non-unit fractions on a number line', 'Mark off repeated unit-fraction lengths to locate a/b.', 3);
INSERT INTO standard_core_ideas (core_idea_id, standard_id, name, description, sort_order) VALUES (3104, 3001, 'Explain fraction value using the number line', 'Explain why the endpoint represents the value of the fraction.', 4);
INSERT INTO standard_core_ideas (core_idea_id, standard_id, name, description, sort_order) VALUES (5101, 5001, 'Determine the main idea or theme', 'Identify the central meaning of an informational or literary text.', 1);
INSERT INTO standard_core_ideas (core_idea_id, standard_id, name, description, sort_order) VALUES (5102, 5001, 'Identify key supporting details', 'Select details that directly support the main idea or theme.', 2);
INSERT INTO standard_core_ideas (core_idea_id, standard_id, name, description, sort_order) VALUES (5103, 5001, 'Explain how details convey the main idea or theme', 'Connect specific details to the development of the text''s central meaning.', 3);
INSERT INTO standard_core_ideas (core_idea_id, standard_id, name, description, sort_order) VALUES (5104, 5001, 'Summarize the text', 'Produce a concise summary that preserves the important ideas and details.', 4);
INSERT INTO standard_core_ideas (core_idea_id, standard_id, name, description, sort_order) VALUES (7101, 7001, 'Recognize proportional relationships', 'Determine whether two quantities have a proportional relationship.', 1);
INSERT INTO standard_core_ideas (core_idea_id, standard_id, name, description, sort_order) VALUES (7102, 7001, 'Determine the constant of proportionality', 'Find and interpret the unit rate/constant from tables, graphs, equations, or contexts.', 2);
INSERT INTO standard_core_ideas (core_idea_id, standard_id, name, description, sort_order) VALUES (7103, 7001, 'Represent proportional relationships', 'Represent a proportional relationship using equations, tables, and graphs.', 3);
INSERT INTO standard_core_ideas (core_idea_id, standard_id, name, description, sort_order) VALUES (7104, 7001, 'Apply proportional reasoning in context', 'Solve and explain real-world proportional relationship problems.', 4);
INSERT INTO standard_core_ideas (core_idea_id, standard_id, name, description, sort_order) VALUES (8101, 8001, 'Model particle motion and state', 'Use particle models to distinguish solids, liquids, and gases.', 1);
INSERT INTO standard_core_ideas (core_idea_id, standard_id, name, description, sort_order) VALUES (8102, 8001, 'Connect heat energy and particle motion', 'Explain how adding or removing heat changes particle motion and temperature.', 2);
INSERT INTO standard_core_ideas (core_idea_id, standard_id, name, description, sort_order) VALUES (8103, 8001, 'Explain phase change with a model', 'Use evidence and models to explain changes of state.', 3);
INSERT INTO standard_core_ideas (core_idea_id, standard_id, name, description, sort_order) VALUES (8104, 8001, 'Connect mass, volume, and density', 'Calculate and interpret density while connecting it to particle arrangement and state.', 4);
