INSERT INTO plc_instructional_responses (response_id, cycle_id, source_administration_id, mastery_status, response_type, focus_core_idea_id, focus_text, strategy, owner_user_id, reassess_date, created_by_user_id) VALUES (50001, 3001, 33001, 'Mastered', 'Enrichment', 7104, 'Transfer proportional reasoning to unfamiliar contexts', 'Use multi-step application tasks that require students to justify why a relationship is proportional.', 30, '2026-09-18', 30);
INSERT INTO plc_instructional_responses (response_id, cycle_id, source_administration_id, mastery_status, response_type, focus_core_idea_id, focus_text, strategy, owner_user_id, reassess_date, created_by_user_id) VALUES (50002, 3001, 33001, 'Approaching', 'Brief Reteach', 7104, 'Clarify proportional reasoning in context', 'Model how to identify the two quantities, determine the unit rate, and connect the equation back to the context.', 31, '2026-09-18', 31);
INSERT INTO plc_instructional_responses (response_id, cycle_id, source_administration_id, mastery_status, response_type, focus_core_idea_id, focus_text, strategy, owner_user_id, reassess_date, created_by_user_id) VALUES (50003, 3001, 33001, 'Developing', 'Small-Group Instruction', 7102, 'Build constant-of-proportionality understanding', 'Use tables and double number lines before moving to equations and graphs.', 32, '2026-09-18', 32);
INSERT INTO plc_instructional_responses (response_id, cycle_id, source_administration_id, mastery_status, response_type, focus_core_idea_id, focus_text, strategy, owner_user_id, reassess_date, created_by_user_id) VALUES (50004, 3001, 33001, 'Intensive', 'Prerequisite Support', 7101, 'Rebuild ratio and unit-rate prerequisites', 'Use concrete ratio situations and visual models before asking students to generalize a proportional relationship.', 30, '2026-09-18', 30);
